          { id: "branch-2", name: "Branch 2 - Charminar Heritage Outlet", address: "Pathergatti Road, Near Medina Building, Charminar, Hyderabad, Telangana 500002", phone: "7337464501", manager: "Branch Manager (Owner 1)", enabled: true }
